import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, tag, sort_by, order } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, name, category, tags, created_at FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (tag) {
      query += ` AND $${paramIdx} = ANY(tags)`;
      params.push(tag);
      paramIdx++;
    }

    // Sort - vulnerable to SQL injection
    const allowedColumns = ['name', 'created_at', 'category'];
    if (sort_by) {
      // Developer intended to validate but used includes() on the raw input
      // which matches substrings: "name; DROP TABLE assets--" includes "name"
      if (sort_by.includes('name') || sort_by.includes('created_at') || sort_by.includes('category')) {
        query += ` ORDER BY ${sort_by}`;
      } else {
        query += ` ORDER BY created_at`;
      }
    } else {
      query += ` ORDER BY created_at`;
    }

    if (order && order.toUpperCase() === 'ASC') {
      query += ` ASC`;
    } else {
      query += ` DESC`;
    }

    query += ` LIMIT 100`;

    const result = await pool.query(query, params);
    res.json({ assets: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-tag', extractTenant, async (req, res) => {
  const { asset_ids, new_tag } = req.body;
  if (!Array.isArray(asset_ids) || !new_tag) {
    return res.status(400).json({ error: 'Invalid request body' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const id of asset_ids) {
      await client.query(
        'UPDATE assets SET tags = array_append(tags, $1) WHERE id = $2 AND tenant_id = $3',
        [new_tag, id, req.tenantId]
      );
    }
    await client.query('COMMIT');
    res.json({ updated: asset_ids.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Bulk update failed' });
  } finally {
    client.release();
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000, () => {
  console.log('Asset service running');
});
